'use strict';
const C=window.CURRICULUM;
const $=(q,root=document)=>root.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const find=(kind,id)=>C[kind].find(x=>x.id===id);
const link=(route,label,cls='')=>`<a class="${cls}" href="#/${route}">${label}</a>`;
const badge=(text,type='planned')=>`<span class="badge ${type}">${text}</span>`;
const button=(label,action,cls='')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;
const note=(title,text,type='')=>`<div class="notice ${type}"><strong>${title}</strong><p>${text}</p></div>`;
const crumbs=(items)=>`<nav class="breadcrumb" aria-label="Breadcrumb">${link('home','Home')}${items.map(([r,t])=>`<span aria-hidden="true">/</span>${r?link(r,esc(t)):`<span aria-current="page">${esc(t)}</span>`}`).join('')}</nav>`;
const head=(eyebrow,title,lead)=>`<div class="page-head"><p class="eyebrow">${eyebrow}</p><h1 tabindex="-1">${title}</h1>${lead?`<p class="lead">${lead}</p>`:''}</div>`;
const sample=()=>note('Design specimen','This screen illustrates a future reviewed learning experience. The current curriculum has no published lessons. Learner records and outcomes shown here are samples.');
const hours=x=>Array.isArray(x)?`${x[0]}–${x[1]} hours`:'Estimate not established';
let state={theme:'light',scenario:'ready',bookmark:false,complete:false,note:'',noteSaved:'',practiceSolution:false,quizFeedback:false,quizAnswer:'',signedIn:false,editorDirty:false};
let route={page:'home',id:'',params:new URLSearchParams()};
let restoreFocus=null;
function announce(text){$('#announcer').textContent=text;}
function navigate(dest){location.hash='#/'+dest;}
function base(content,cls=''){return `<div class="container ${cls}">${content}</div>`;}
function personalNav(active){return `<nav class="subnav" aria-label="My learning">${['dashboard','bookmarks','notes','account'].map((x,i)=>`<a href="#/${x}" ${x===active?'aria-current="page"':''}>${['Overview','Bookmarks','Private notes','Account'][i]}</a>`).join('')}</nav>`;}
function editorNav(active){return `<nav class="subnav" aria-label="Editorial workspace">${['admin','editor','publish','maintenance'].map((x,i)=>`<a href="#/${x}" ${x===active?'aria-current="page"':''}>${['Review queue','Draft editor','Publication','Maintenance'][i]}</a>`).join('')}</nav>`;}
function home(){return base(`<section class="hero"><div><p class="eyebrow">An ordered approach to options</p><h1>Understand the contract.<br><em>Then the risk.</em></h1><p class="lead">A learning path through obligations, cash flows and uncertainty. Begin with the mechanics. Build toward research and professional practice.</p><div class="actions">${link('learn','Explore Foundations <span aria-hidden="true">↗</span>','button primary')}${link('curriculum','View the curriculum','button')}</div><p class="small muted">Free to explore. No trading account required.<br>Foundations is in preparation.</p></div><aside class="course-sheet" aria-label="Foundation course preview"><p class="eyebrow">Begin here · R1 Foundations</p><h2>Contracts, cash<br>and risk.</h2>${badge('Course in preparation','warn')}<div style="margin-top:24px">${[['01','Read the contract','Rights, obligations and units'],['02','Follow the cash','Premium, assignment and costs'],['03','Question the risk','Loss, collateral and uncertainty']].map(x=>`<div class="sheet-row"><span>${x[0]}</span><div><strong>${x[1]}</strong><span>${x[2]}</span></div></div>`).join('')}</div><p class="small muted" style="margin-top:24px;margin-bottom:0">36 planned lessons · 6 assessment gates<br>28–49 hours · editorial estimate</p></aside></section><section class="stats-line" aria-label="Current curriculum snapshot">${[['70','module designs'],['1,025','topic scopes'],['96','resource records'],['0','reviewed lessons']].map(x=>`<div class="stat"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</section><section><div class="section-heading"><h2>Find your starting point.</h2>${link('paths','All seven learning paths →')}</div><div class="grid-3">${[['PATH-BEGINNER','Build a foundation','Begin with arithmetic, obligations and a clear account of risk.'],['PATH-QUANT','Connect the mathematics','Trace the preparation for pricing, numerical methods and research.'],['PATH-INDIA','Study the local context','Locate India-specific topics and the evidence their rules require.']].map(([id,title,desc])=>link('path/'+id,`<p class="label">${esc(find('learning_paths',id)?.title||id)}</p><h3>${title}</h3><p class="muted">${desc}</p>${badge('Planned path')}<p class="small" style="margin-top:16px">Explore scope <span aria-hidden="true">↗</span></p>`,'panel panel-link')).join('')}</div></section><section class="grid-2" style="margin-top:64px"><div><p class="eyebrow">The learning method</p><h2>From an explanation<br>to evidence.</h2><p class="lead">Read an original example. Work through a changed case. Use feedback to explain what happened—and what your calculation leaves out.</p>${link('methodology','How review and assessment work →')}</div><div class="thin-rule">${[['01','Read & reason','Understand assumptions, units and the limit of each claim.'],['02','Practice & revisit','Make a calculation, inspect the feedback and try a new input.'],['03','Demonstrate & reflect','Separate fresh assessment evidence from self-completion.']].map(x=>`<div class="list-row"><span class="number">${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}</div></section><section><div class="section-heading"><h2>Put the reasoning to work.</h2>${link('projects','Project & capstone specifications →')}</div><div class="grid-2">${['PR01','PR02'].map(id=>{const p=find('projects',id);return link('project/'+id,`<p class="label">${id} · ${hours(p.study_hours)}</p><h3>${esc(p.title)}</h3><p class="muted">${esc(p.learning_objective)}</p>${badge('Specification · no workspace')}`,'panel panel-link');}).join('')}</div></section>`);}
function learn(){return base(`${crumbs([['','Foundations']])}${head('R1 Foundations','Contracts, cash and risk.','A finite beginning: learn to read a hypothetical option contract, trace cash obligations and explain the limits of a payoff calculation.')}<div class="split"><section>${note('Course in preparation','0 of 36 lessons and 0 of 6 assessment packs have completed review. You can inspect the sequence now. Enrollment opens only when the complete course is ready.','warn')}<h2>Your first six lessons</h2><ol class="list">${['M01.01','M01.02','M01.06','M01.07','M01.11','B01.01'].map((id,i)=>{const t=find('topics',id);return `<li class="list-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${link('topic/'+id,esc(t.title))}</h3><p>${esc(t.scope_outline)}</p></div>${badge('Planned')}</li>`;}).join('')}</ol><div class="notice"><strong>Reading stays open.</strong><p>Published lessons will be readable without signing in. A verified account will save your work and provide access to the untimed entry diagnostic.</p></div><div class="actions">${link('lesson/M01.01','Review a lesson layout','button')}${link('quiz','Review assessment layout','button')}</div></section><aside class="side-rail"><h2>What the course includes</h2><ul><li>36 lessons</li><li>6 scored assessment gates</li><li>1 self-reviewed cash dossier</li><li>No coding or paid reading requirement</li></ul><p>28–49 hours is an editorial planning estimate, including practice and optional remediation.</p><h2>What comes after</h2><p>The seven larger paths remain planned. Completing Foundations does not complete a whole specialist path.</p>${link('paths','Explore the planned paths →')}</aside></div>`);}
function curriculum(){return base(`${crumbs([['','Curriculum']])}${head('The complete map','A curriculum with a visible horizon.','Five phases connect the foundations to advanced practice. These are reviewed design records; lesson publication is a separate milestone.')}<div class="split"><section>${C.phases.map((p,i)=>`<details class="phase" ${i===0?'open':''}><summary>${esc(p.id)} · ${esc(p.title)} <span>${p.module_ids.length} modules · planned</span></summary><div class="phase-content"><ol class="list">${p.module_ids.map(id=>{const m=find('modules',id);return `<li class="list-row"><span class="number">${id}</span><div><h3>${link('module/'+id,esc(m.title))}</h3><p>${esc(m.why_it_matters)}</p><span class="small muted">${esc(m.level)} · ${hours(m.study_hours)}</span></div></li>`;}).join('')}</ol></div></details>`).join('')}</section><aside class="side-rail"><h2>Read the map</h2><p><strong>Planned scope</strong><br>What a future lesson must teach.</p><p><strong>Published lesson</strong><br>Instruction and practice that have passed review.</p><p><strong>Hard preparation</strong><br>Evidence required before an assessment; public reading stays open.</p><p>Lists show the same relationships as any future diagram. No dragging or wide canvas is required.</p>${link('learn','Explore the foundation sequence →')}</aside></div>`);}
function modulePage(id){const m=find('modules',id);if(!m)return notFound();return base(`${crumbs([['curriculum','Curriculum'],['',m.id]])}${head(m.id+' · '+esc(m.level),esc(m.title),esc(m.why_it_matters))}<div class="metadata">${badge('Module design')}<span>${hours(m.study_hours)} · full-module estimate</span><span>${m.topic_ids.length} topic scopes</span></div><div class="split"><section><h2>What you will learn</h2><ul>${m.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${note('A scope, not a finished course','This module contains planned instruction. Foundations uses selected topics; completing that subset will not mark the whole module complete.','warn')}<h2>Topics in this module</h2><ol class="list">${m.topic_ids.map((id,i)=>{const t=find('topics',id);return `<li class="list-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${link('topic/'+id,esc(t?.title||id))}</h3><p>${esc(t?.scope_outline||'Scope being prepared.')}</p></div>${badge('Planned')}</li>`;}).join('')}</ol><h2 style="margin-top:40px">Common mistakes to examine</h2><ul>${(m.common_mistakes||['Check units, signs and the assumptions behind a result.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><aside class="side-rail"><h2>Preparation</h2>${['hard','recommended','optional'].map(k=>`<h3 class="small">${{hard:'Required for assessment',recommended:'Recommended',optional:'Optional enrichment'}[k]}</h3><p>${m.prerequisites[k]?.length?m.prerequisites[k].map(x=>link('module/'+x,esc(x))).join(', '):'None specified.'}</p>`).join('')}<h2>Reading</h2><p>Resource assignments are reviewed at the section level. A broad module link is not an exact citation for every topic.</p>${link('resources','Inspect resource scopes →')}<hr><p>${esc(m.estimate_basis)}</p></aside></div>`);}
function topicPage(id){const t=find('topics',id);if(!t)return notFound();return base(`${crumbs([['curriculum','Curriculum'],['module/'+t.module_id,t.module_id],['',t.title]])}${head(t.id+' · Planned scope',esc(t.title),esc(t.scope_outline))}<div class="split"><section>${note('This lesson is being prepared','The scope is available to inspect. The explanation, worked examples, practice and feedback are not yet published.','warn')}<h2>Within this topic</h2>${t.subtopic_ids.map(x=>`<div class="panel"><p class="label">${esc(x)}</p><h3>${esc(t.title)} — scope unit</h3><p>${esc(t.scope_outline)}</p>${badge('Independently addressable scope')}</div>`).join('')}<h2 style="margin-top:40px">Continue exploring</h2><p>Inspect the broader module or the foundation course sequence. There is no completion or quiz action for an unpublished topic.</p><div class="actions">${link('module/'+t.module_id,'Back to module','button')}${link('learn','Foundation sequence','button')}</div></section><aside class="side-rail"><h2>Topic details</h2><p>${esc(t.difficulty)}<br>${esc(t.priority)}</p><div class="chip-list">${t.tags.map(x=>badge(esc(x),'planned')).join('')}</div><hr><h2>For this design review</h2><p>A separate reading specimen shows the intended lesson layout. It is not a published lesson.</p>${link('lesson/M01.01','Open the reading specimen →')}</aside></div>`);}
const toc=()=>`<a href="#units">Read the units</a><a href="#worked">Worked example</a><a href="#practice">Try it yourself</a><a href="#sources">Reading & next step</a>`;
function lesson(){return base(`${crumbs([['learn','Foundations'],['module/M01','M01'],['','Units and signs']])}<div class="reading-layout"><aside class="reading-nav" aria-label="Lesson outline"><h2>In this lesson</h2>${toc()}<hr><p class="muted">F01 of 36<br>Units and signs</p>${link('learn','← Course sequence')}</aside><article class="reading"><p class="eyebrow">Foundations · Lesson layout specimen</p><h1 tabindex="-1">Units and signs</h1><p class="lead">A quote is not a cash flow until you know its unit, multiplier and direction.</p><div class="metadata">${badge('Illustrative published state','')}<span>M01.01 · Beginner</span><span>Reading sample, not a complete lesson</span></div>${sample()}<details class="lesson-mobile-toc"><summary>In this lesson</summary>${toc()}</details><p>This design sample uses a hypothetical contract. A price stated per unit and an amount for a whole contract describe different things. Write the unit next to each number before doing the arithmetic.</p><h2 id="units">First, name the quantity.</h2><p>Suppose a quote is <strong>2 currency units per unit of the underlying</strong>. The hypothetical contract has a multiplier of <strong>50 units per contract</strong>. One contract therefore represents 100 currency units of premium.</p><div class="formula" tabindex="0" role="region" aria-label="Premium formula"><math display="block" aria-label="Premium cash equals quote times multiplier times contracts"><mrow><mi>C</mi><mo>=</mo><mi>q</mi><mo>×</mo><mi>m</mi><mo>×</mo><mi>n</mi></mrow></math></div><p class="small muted">C is premium cash; q is the per-unit quote; m is units per contract; n is contract count. This calculation excludes fees and other cash flows.</p><h2 id="worked">Follow the sign as well as the unit.</h2><p>Choose the account’s perspective. Cash paid out has a negative sign. Cash received has a positive sign. A premium receipt by itself does not describe the position’s total risk.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Hypothetical premium ledger"><table><caption>Hypothetical premium only · one contract, no fees</caption><thead><tr><th scope="col">Entry</th><th scope="col" class="numeric">Calculation</th><th scope="col" class="numeric">Cash</th></tr></thead><tbody><tr><th scope="row">Buyer pays</th><td class="numeric">−2 × 50 × 1</td><td class="numeric">−100</td></tr><tr><th scope="row">Writer receives</th><td class="numeric">+2 × 50 × 1</td><td class="numeric">+100</td></tr></tbody></table></div><div class="notice warn"><strong>Common mistake</strong><p>Do not substitute the premium received for the largest possible loss or a later funding obligation. Those are separate questions.</p></div><section class="practice" id="practice" aria-labelledby="practice-title"><p class="eyebrow">A changed input · layout sample</p><h2 id="practice-title">Try it yourself.</h2><p>The quote is now 3 currency units per unit. With the same multiplier of 50, what premium does a buyer <strong>pay out</strong> for one contract? Enter a signed amount.</p><form id="practice-form"><label for="practice-answer">Signed premium cash (currency units)</label><input id="practice-answer" name="answer" inputmode="decimal" aria-describedby="practice-help" autocomplete="off"><p id="practice-help" class="helper">Use a minus sign for cash paid. No fees in this example.</p><div class="actions"><button class="primary" type="submit">Check my reasoning</button>${button('Show the reference','solution','text-button')}</div></form><div id="feedback" role="status" aria-live="polite"></div></section><h2 id="sources">Reading with a defined scope.</h2><p>This interface separates a resource’s access check from its substantive review. The record below is a canonical example of a bibliography card, not a claim that this sample lesson has passed source review.</p><div class="panel"><p class="label">Essential · R01 · OCC</p><h3>${link('resource/R01','Characteristics and Risks of Standardized Options')}</h3><p class="small muted">Selected sections reviewed · 22 September 2026<br>Contents and selected II/VIII/X excerpts; not all 96 pages.</p></div><section class="personal"><h2>Keep your place.</h2><div class="actions">${button(state.complete?'Reopen topic':'Mark self-completed','complete','primary')}${button(state.bookmark?'Remove bookmark':'Bookmark topic','bookmark')}${link('notes','Write a private note','button')}</div><p class="small muted" id="completion-status">${state.complete?'Self-completed in this sample. This is not assessment mastery.':'Self-completion records your own reading. Assessment evidence is shown separately.'}</p></section><hr><p class="eyebrow">Next in Foundations</p><h3>${link('topic/M01.02','02 · Percent change →')}</h3><p class="small muted">Current content: planned scope. A released course will link to its next available lesson.</p></article></div>`);}
function resources(){const q=route.params.get('q')||'', cost=route.params.get('cost')||'',difficulty=route.params.get('difficulty')||'', priority=route.params.get('priority')||'',sort=route.params.get('sort')||'priority';let rs=C.resources.filter(r=>(!cost||r.cost===cost)&&(!difficulty||r.difficulty===difficulty)&&(!priority||r.priority===priority)&&(!q||(r.title+' '+r.author_organization+' '+r.id).toLowerCase().includes(q.toLowerCase())));const order=['Essential','Very Important','Recommended','Useful','Advanced','Specialized','Optional','Reference'];rs.sort((a,b)=>(sort==='priority'?(order.indexOf(a.priority)-order.indexOf(b.priority)):sort==='duration'?a.study_hours[0]-b.study_hours[0]:sort==='-verified'?(b.last_verification_date||'').localeCompare(a.last_verification_date||''):0)||a.title.localeCompare(b.title)||a.id.localeCompare(b.id));const page=+(route.params.get('page')||0),shown=rs.slice(page*20,page*20+20);return base(`${crumbs([['','Resources']])}${head('The reading library','Read with a purpose.','Books, primary research and official documentation, with exact review scope and honest access limits. No popularity ratings.')}<form id="resource-filters"><div class="toolbar"><div class="grow"><label for="resource-query">Find a title, author or resource ID</label><input id="resource-query" name="q" value="${esc(q)}" placeholder="For example, OCC or Natenberg" maxlength="200"></div><button class="primary" type="submit">Search library</button></div><details class="filters" open><summary>Refine your reading</summary><div class="filters-content"><div class="filter-grid">${selectField('cost','Access',['free','mixed','paid'],cost,{free:'Free',mixed:'Mixed access',paid:'Paid'})}${selectField('difficulty','Difficulty',[...new Set(C.resources.map(x=>x.difficulty))].sort(),difficulty)}${selectField('priority','Priority',order.filter(x=>C.resources.some(y=>y.priority===x)),priority)}</div><div class="actions"><button type="submit">Apply filters</button>${link('resources','Clear filters')}</div><p class="helper">Difficulty labels preserve the source range. “Beginner” does not automatically include “Beginner–Advanced”. Additional production facets: type, topic/tag, phase, path, source, geography and review status.</p></div></details><div class="toolbar"><p class="grow" role="status">${rs.length} matching records · ${page*20+1>rs.length?0:page*20+1}–${Math.min((page+1)*20,rs.length)} shown</p><div>${selectField('sort','Sort by',['priority','title','duration','-verified'],sort,{priority:'Editorial priority',title:'Title A–Z',duration:'Estimated study time','-verified':'Substantive review: newest'})}</div><button type="submit">Update order</button></div></form><section aria-label="Resource results">${shown.length?shown.map(r=>`<article class="resource"><span class="id">${r.id}</span><div><h2>${link('resource/'+r.id,esc(r.title))}</h2><p class="muted">${esc(r.author_organization)} · ${esc(r.resource_type)}</p><p>${esc(r.rationale)}</p><div class="metadata">${badge(esc(r.priority),'')}<span>${esc(r.difficulty)}</span><span>${esc(r.cost==='mixed'?'Mixed access':r.cost==='free'?'Free':'Paid')}</span><span>${hours(r.study_hours)}</span></div><p class="small muted">${r.status==='selected_sections_reviewed'?'Selected sections reviewed':r.status==='limited_review'?'Limited review':'Access / inherited metadata only'} · ${esc(r.last_verification_date||'Date not established')}</p></div><div>${link('resource/'+r.id,'Inspect scope <span aria-hidden="true">↗</span>','button')}</div></article>`).join(''):note('No resources match','Try removing a filter. An empty result does not mean that a source or topic does not exist.')}</section><nav class="pagination" aria-label="Results pages">${page?link('resources?'+withParams({page:page-1}),'← Previous','button'):''}<span class="small muted">Page ${page+1} · 20 per page in this prototype</span>${(page+1)*20<rs.length?link('resources?'+withParams({page:page+1}),'Next 20 →','button'):''}</nav>`);}
function withParams(values){const p=new URLSearchParams(route.params);Object.entries(values).forEach(([k,v])=>p.set(k,v));return p.toString();}
function selectField(name,label,values,current,labels={}){return `<div><label for="filter-${name}">${label}</label><select id="filter-${name}" name="${name}">${name!=='sort'?'<option value="">All</option>':''}${values.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(labels[x]||x)}</option>`).join('')}</select></div>`;}
function resourceDetail(id){const r=find('resources',id);if(!r)return notFound();return base(`${crumbs([['resources','Resources'],['',id]])}${head(esc(r.id)+' · '+esc(r.priority),esc(r.title),esc(r.rationale))}<div class="metadata"><span>${esc(r.author_organization)}</span><span>${esc(r.resource_type)}</span>${badge(esc(r.cost),'')}<span>${esc(r.difficulty)}</span></div><div class="split"><section><h2>What was reviewed</h2><div class="notice"><strong>${esc(r.last_verification_date)} · substantive review record</strong><p>${esc(r.verification_scope)}</p></div><h2>Access before you follow the link</h2><p>${esc(r.access_limitations)}</p><p class="muted">${esc(r.rights)}</p><div class="actions"><a class="button primary" href="${esc(r.canonical_url)}" target="_blank" rel="noopener noreferrer">Open the source <span aria-hidden="true">↗</span><span class="sr-only"> (opens a new tab)</span></a>${button(state.bookmark?'Remove bookmark':'Bookmark resource','bookmark')}</div><h2 style="margin-top:40px">Assignment scope matters</h2><p>A resource’s relevance to a competency does not establish an exact reading assignment for every associated topic. Required lesson readings will identify the section, purpose and reviewed alternative.</p>${link('lesson/M01.01','Review a lesson citation layout →')}</section><aside class="side-rail"><h2>Bibliographic details</h2><p><strong>Publication date</strong><br>${esc(r.publication_date||'Not established')}</p><p><strong>Study estimate</strong><br>${hours(r.study_hours)} for selected study, not the whole publication</p><p><strong>Geography</strong><br>${esc(r.geography)}</p><h2>Source freshness</h2><p>Link reachability and substantive verification are separate. This design snapshot does not certify a current operational rule.</p>${link('report/'+id,'Report a content issue →')}</aside></div>`);}
function pathsPage(){return base(`${crumbs([['','Paths']])}${head('Seven connected views','Choose a direction.','Each path reuses the same curriculum. Prerequisites explain the preparation; planned work stays visible.')}<div class="notice"><strong>Looking for a finite first course?</strong><p>Foundations is the 36-lesson release being prepared. The paths below require further authoring and cannot yet be completed.</p>${link('learn','Explore Foundations →')}</div><div class="grid-2">${C.learning_paths.map(p=>link('path/'+p.id,`<p class="label">${esc(p.id)}</p><h2>${esc(p.title)}</h2><p>${esc(p.entry_criteria)}</p><p class="small muted">${p.module_sequence.length} shared modules · ${hours(p.study_hours)}</p>${badge('Planned path')}`,'panel panel-link')).join('')}</div>`);}
function pathDetail(id){const p=find('learning_paths',id);if(!p)return notFound();return base(`${crumbs([['paths','Paths'],['',p.title]])}${head('Planned path · '+esc(p.id),esc(p.title),esc(p.entry_criteria))}<div class="split"><section>${note('Instruction remains planned','This path is a view of the whole intended sequence. Foundations alone does not complete it. Enrollment is unavailable until every required lesson and assessment is ready.','warn')}<h2>Shared sequence</h2><ol class="list">${p.module_sequence.map((id,i)=>`<li class="list-row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${link('module/'+id,esc(find('modules',id)?.title||id))}</h3><p>${id} · ${hours(find('modules',id)?.study_hours)}</p></div>${badge('Planned')}</li>`).join('')}</ol></section><aside class="side-rail"><h2>Intended exit outcomes</h2><ul>${p.exit_competencies.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>${hours(p.study_hours)}</h2><p>${esc(p.estimate_basis)}</p>${link('learn','Start with the foundation plan →')}</aside></div>`);}
function projects(){return base(`${crumbs([['','Projects']])}${head('Practice with a deliverable','Make the reasoning inspectable.','Twelve capability projects and seven capstone briefs describe the broader learning goals. Their coding workspaces and formal grading remain planned.')}<div class="next-card"><div><p class="eyebrow">The foundation release · R1-CASE-01</p><h2>Cash and obligations dossier</h2><p>One manual worksheet, signed cash flows and a structured self-review. No file upload or code runtime.</p></div>${link('dossier','Review dossier layout','button primary')}</div><div class="section-heading"><h2>Capability projects</h2><span class="small muted">12 specifications</span></div><div class="grid-2">${C.projects.map(p=>link('project/'+p.id,`<p class="label">${p.id} · ${hours(p.study_hours)}</p><h3>${esc(p.title)}</h3><p class="muted">${esc(p.learning_objective)}</p>${badge('Planned specification')}`,'panel panel-link')).join('')}</div><div class="section-heading"><h2>Capstone briefs</h2><span class="small muted">7 preserved briefs</span></div><ol class="list">${C.capstones.map(c=>`<li class="list-row"><span class="number">${c.id}</span><div><h3>${link('capstone/'+c.id,esc(c.title))}</h3><p>${esc(c.original_brief)}</p></div>${badge('Planned')}</li>`).join('')}</ol>`);}
function project(id,cap=false){const p=find(cap?'capstones':'projects',id);if(!p)return notFound();return base(`${crumbs([['projects','Projects'],['',id]])}${head((cap?'Capstone brief':'Project specification')+' · '+id,esc(p.title),esc(cap?p.original_brief:p.learning_objective))}<div class="split"><section>${note('Specification only','There is no hosted workspace, upload or instructor grading for this project in the first release.','warn')}<h2>${cap?'Related project':'Proposed deliverables'}</h2>${cap?`<p>${p.project_ids.map(id=>link('project/'+id,esc(id))).join(', ')}</p>`:`<p>${esc(p.deliverables)}</p><h2>Work through the problem</h2><ol>${p.steps.map(x=>`<li>${esc(x.trim())}</li>`).join('')}</ol><h2>Data and rights</h2><p>${esc(p.data_plan)}</p><h2>Limits of the result</h2><p>${esc(p.limitations)}</p>`}<div class="actions">${link('projects','Back to all specifications','button')}</div></section><aside class="side-rail"><h2>Preparation</h2>${cap?'<p>Inspect the connected project and its prerequisite modules.</p>':`<ul>${p.prerequisites.map(id=>`<li>${link('module/'+id,esc(id))}</li>`).join('')}</ul><h2>Estimated effort</h2><p>${hours(p.study_hours)}</p><p>${esc(p.noncoding_route)}</p>`}</aside></div>`);}
function search(){const q=route.params.get('q')||'',ready=route.params.get('visibility')==='LESSON';let hits=[...C.topics.map(x=>({...x,kind:'Topic',to:'topic/'+x.id})),...C.modules.map(x=>({...x,kind:'Module',to:'module/'+x.id})),...C.resources.map(x=>({...x,kind:'Resource',to:'resource/'+x.id}))].filter(x=>!ready&&(!q||(x.id+' '+x.title+' '+(x.author_organization||'')).toLowerCase().includes(q.toLowerCase()))).sort((a,b)=>(b.id.toLowerCase()===q.toLowerCase())-(a.id.toLowerCase()===q.toLowerCase())||a.title.localeCompare(b.title));return base(`${head('Search the public curriculum','Find the next question.','Search titles, authors and stable IDs. Planned scope appears alongside published instruction; private notes and quiz answers are never searched.')}<form id="search-form"><div class="toolbar"><div class="grow"><label for="global-q">Search term</label><input id="global-q" name="q" value="${esc(q)}" maxlength="200" placeholder="M21.01, assignment, Natenberg or margin"></div><button type="submit" class="primary">Search</button></div><label class="choice" style="max-width:350px"><input type="checkbox" name="ready" ${ready?'checked':''}>Ready to learn: published lessons only</label></form><p role="status" class="muted">${hits.length} matches in the design snapshot · first ${Math.min(20,hits.length)} shown</p>${hits.length?`<ol class="list">${hits.slice(0,20).map(x=>`<li class="list-row"><span class="number">${esc(x.kind)}</span><div><h3>${link(x.to,esc(x.title))}</h3><p>${esc(x.id)} · ${esc(x.scope_outline||x.why_it_matters||x.rationale||'')}</p></div>${badge('Planned / catalog')}</li>`).join('')}</ol>`:note('No matching published instruction','The current snapshot has zero reviewed lessons. Clear “Ready to learn” to inspect planned scope. This is not a search failure.')}<p class="helper" style="margin-top:24px">Prototype search demonstrates ID/title matching only. Production uses P05’s full relevance, facets and bounded pagination.</p>`);}
function auth(mode='login'){const config={login:['Welcome back.','Sign in to continue your saved learning.','Sign in'],register:['Keep your learning together.','Create an account to save notes, bookmarks and assessment evidence. Reading stays open.','Create account'],verify:['Check your email.','Use the most recent verification message. Verify your address before saving learning records.','Resend verification'],forgot:['Reset your password.','If the address is eligible, we will send the next step.','Request reset link'],reset:['Choose a new password.','Reset links expire after 30 minutes and can only be used once.','Save new password'],mfa:['Confirm it’s you.','Use a registered security key or passkey to enter the editorial workspace.','Use security key'],reauth:['Sign in again to continue.','Your session expired. Unsaved writing remains in this tab until you leave or switch accounts.','Continue securely']}[mode]||['Welcome back.','','Sign in'];return base(`${crumbs([['','Account']])}<div class="auth-layout"><section>${head('Your account',config[0],config[1])}<p class="helper">Design form: use fictional details only. No account is created and no message is sent.</p><form id="auth-form" data-mode="${mode}" class="form-stack" novalidate>${['login','register','forgot'].includes(mode)?'<div><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required><p id="email-error" class="field-error" hidden></p></div>':''}${['login','register','reset','reauth'].includes(mode)?`<div><label for="password">${mode==='reset'?'New password':'Password'}</label><input id="password" name="password" type="password" autocomplete="${['register','reset'].includes(mode)?'new-password':'current-password'}" ${['register','reset'].includes(mode)?'minlength="15"':''} maxlength="128" required aria-describedby="password-help"><p id="password-help" class="helper">${['register','reset'].includes(mode)?'15–128 characters. Spaces, paste and password managers are welcome.':'Password managers and paste are supported.'}</p>${button('Show password','show-password','text-button')}</div>`:''}${mode==='register'?'<label class="choice"><input type="checkbox" name="eligible" required>I meet the stated eligibility policy.</label><p class="helper">Final eligibility and privacy wording requires operator review before registration launches.</p>':''}<div class="actions"><button type="submit" class="primary">${config[2]}</button>${mode==='login'?link('auth/forgot','Forgot password?'):''}</div><div id="auth-result" role="status" aria-live="polite"></div></form>${mode==='login'?`<p class="small">New here? ${link('auth/register','Create an account')}</p>`:''}${mode==='mfa'?`<p class="small">No access to this key? Use your separately registered backup. Email recovery restores learner access only.</p>`:''}${link('learn','Continue reading without signing in →')}</section><aside class="auth-aside"><p class="eyebrow">A record of your learning</p><h2>Your progress.<br>Your pace.</h2><ul><li>Resume a versioned course.</li><li>Keep your notes private.</li><li>Distinguish reading from demonstrated evidence.</li><li>Export or delete your own records.</li></ul><p class="small muted">There are no public profiles, rankings or streaks to maintain.</p></aside></div>`);}
function dashboard(){return base(`${personalNav('dashboard')}${head('My learning · sample account','Pick up the thread.','Foundations: contracts, cash and risk · enrolled course version 1')} ${sample()}<section class="progress-metrics" aria-label="Separate measures of learning"><div><span class="label">Lessons self-completed</span><strong>18 <span class="muted">/ 36</span></strong><div class="progress" role="progressbar" aria-label="Lessons self-completed" aria-valuenow="18" aria-valuemin="0" aria-valuemax="36"><span style="width:50%"></span></div><p class="small muted">Your own reading record</p></div><div><span class="label">Assessment gates passed</span><strong>3 <span class="muted">/ 6</span></strong><p class="small muted">Fresh, scored evidence</p></div><div><span class="label">Cash dossier</span><strong>Not yet reviewed</strong><p class="small muted">A separate self-review</p></div></section><section class="next-card"><div><p class="eyebrow">Recommended next step</p><h2>Revisit cash and assignment.</h2><p>Your most recent sample assessment identified a critical cash-obligation error. Complete the targeted practice before taking the other fresh form.</p></div>${link('feedback','Review feedback','button primary')}</section><div class="grid-2" style="margin-top:40px"><section><div class="section-heading" style="margin-top:0"><h2>Your saved places</h2>${link('bookmarks','All bookmarks →')}</div><div class="list-row"><div><h3>${link('lesson/M01.01','Units and signs')}</h3><p>Foundation course · M01.01</p></div>${badge('Saved sample','')}</div><div class="list-row"><div><h3>${link('resource/R01','OCC options disclosure document')}</h3><p>Resource · R01</p></div></div></section><section class="panel"><p class="eyebrow">A new course version</p><h2>Your denominator stays put.</h2><p>A changed course will not silently turn 18 of 36 into 18 of 37. Review the differences and choose whether to move.</p>${button('Compare course versions','migration')}<p class="helper">Sample state only. Your current evidence and history would be preserved.</p></section></div>`);}
function bookmarks(){return base(`${personalNav('bookmarks')}${head('Saved places','Keep a useful reference close.','Bookmarks attach to stable topics, modules and resources. A retired item remains identifiable.')}<div id="bookmark-list">${state.bookmark?`<div class="list-row"><div><h3>${link('lesson/M01.01','Units and signs')}</h3><p>M01.01 · sample bookmark</p></div>${button('Remove bookmark','remove-bookmark')}</div>`:note('No bookmarks in this preview yet','Open the lesson specimen and choose Bookmark topic. The preview keeps it only until this page is refreshed.')}</div><div class="actions">${link('lesson/M01.01','Open lesson specimen','button')}</div>`);}
function notes(){return base(`${personalNav('notes')}${head('Private notes','Write the distinction you want to remember.','One note per topic, module or resource. Notes are plain text and visible only to their owner.')}<div class="split"><section class="panel"><p class="label">M01.01 · Units and signs</p><form id="note-form"><label for="note-text">Your note</label><textarea id="note-text" name="text" maxlength="10000" aria-describedby="note-help">${esc(state.note)}</textarea><p id="note-help" class="helper">Up to 10,000 characters. This prototype does not save to a server or browser storage.</p><p id="note-status" role="status" aria-live="polite">${state.noteSaved?'Saved in this preview only.':'No saved changes.'}</p><div class="actions"><button class="primary" type="submit">Save note</button>${button('Delete note','delete-note','danger')}${button('Review a conflict','conflict','text-button')}</div></form></section><aside class="side-rail"><h2>When a save is interrupted</h2><p>Your text stays visibly unsaved in this tab. Copy it or retry deliberately after reconnecting.</p><p>If another tab changed the note, compare both versions before applying yours. No silent overwrite.</p>${link('lesson/M01.01','Return to the lesson →')}</aside></div>`);}
function account(){return base(`${personalNav('account')}${head('Your account','A small profile. Clear controls.','Only the information needed to maintain your account and learning records.')}<div class="grid-2"><section class="panel"><h2>Preferences</h2><form id="preferences-form"><label for="display-name">Display name (optional)</label><input id="display-name" maxlength="100" placeholder="Use a fictional name"><div style="margin-top:20px">${selectField('interest','Learning interest',C.learning_paths.map(x=>x.title),'')}</div><div class="actions"><button class="primary" type="submit">Save preferences</button></div><p id="preferences-status" role="status"></p></form><h3>Account security</h3><div class="actions">${link('auth/reset','Change password','button')}${button('Change email','email-change')}${link('auth/mfa','Security key setup','button')}</div><p class="small muted">An email change keeps your current login until the new address is verified. Password changes revoke existing sessions.</p></section><section><div class="panel"><h2>Your records</h2><p>Download your own notes, progress and permitted assessment history. Exports are private and expire 24 hours after becoming ready.</p>${button('Request an export','export')}<p class="helper">Design sample: the ready file state is demonstrated without a download.</p></div><div class="panel" style="margin-top:24px"><h2>Leave with control.</h2><p>Deletion disables your account immediately. Live records are erased within seven days; backup copies expire within 35 days.</p>${button('Delete my account','delete-account','danger')}</div><div class="actions">${button('Sign out','logout')}${button('Sign out everywhere','logout-all')}</div></section></div>`);}
function quiz(){return base(`${crumbs([['dashboard','My learning'],['','Assessment']])}${head('Assessment layout · synthetic example','Check the reasoning, not the clock.','The released gate will have ten equally weighted questions and three critical checks. There is no time limit.')}<div class="split"><section>${sample()}<div class="metadata">${badge('Fresh-form layout','')}<span>One isolated sample question</span><span>No real mastery evidence</span></div><form id="quiz-form"><fieldset><legend>1. A hypothetical quote is 3 currency units per unit with 50 units per contract. Which premium cash entry describes the buyer of one contract, before fees?</legend>${[['a','−150 currency units'],['b','+150 currency units'],['c','−3 currency units']].map(([v,t])=>`<label class="choice"><input type="radio" name="answer" value="${v}" ${state.quizAnswer===v?'checked':''}>${t}</label>`).join('')}</fieldset><p class="small muted">This sample is labeled a critical units/sign check. Production feedback appears only after final submission.</p><div class="actions">${button('Save answers','save-answers')}<button class="primary" type="submit">Review & submit</button></div><p id="quiz-status" role="status"></p></form></section><aside class="side-rail"><h2>Before you submit</h2><p>At least nine of ten correct, with all critical checks correct, passes a released gate.</p><p>After a failed form, complete targeted remediation before the other fresh form. Previously seen forms become repeated practice.</p><h2>Your draft</h2><p>Save acknowledges a server response in the product. An interrupted save remains visibly unsaved.</p>${button('Leave this attempt','abandon','text-button')}</aside></div>`);}
function feedback(){return base(`${crumbs([['dashboard','My learning'],['','Assessment feedback']])}${head('Submitted sample · version retained','A useful result points to the next step.','This is a failure/remediation layout specimen, not a score from a real quiz.')}<div class="split"><section><div class="notice warn"><strong>90% in the sample, but a critical check needs work.</strong><p>A strong total does not cancel a critical cash-obligation error. The gate is not passed.</p></div><div class="panel"><p class="label">Critical check · cash versus collateral</p><h2>Separate the obligation from the margin.</h2><p>The feedback for the submitted form belongs here, followed by the learner’s response, the permitted reference and a clear explanation. It must not reveal the other fresh form.</p>${badge('Historical score preserved','warn')}</div><h2 style="margin-top:40px">Prepare for the other fresh form</h2><ol><li>${link('lesson/M01.01','Revisit the named units and cash explanation.')}</li><li>Complete its changed-input transfer practice.</li><li>Explain the distinction in your own words.</li></ol><form id="remediation-form"><label for="explanation">What will you check differently?</label><textarea id="explanation" maxlength="10000"></textarea><div class="actions"><button class="primary" type="submit">Record remediation</button></div><p id="remediation-status" role="status"></p></form></section><aside class="side-rail"><h2>Evidence, with limits</h2><p><strong>Self-completed</strong><br>You marked your reading complete.</p><p><strong>Gate passed</strong><br>A fresh reviewed form met the scoring rule.</p><p><strong>Needs recheck</strong><br>A critical correction requires new evidence; your original score remains.</p><h2>If no fresh form remains</h2><p>Request a new assessment or continue labeled repeated practice. Repeated practice cannot earn fresh evidence.</p>${button('Request fresh assessment','fresh-request')}</aside></div>`);}
function dossier(){return base(`${crumbs([['projects','Projects'],['','Foundation dossier']])}${head('R1-CASE-01 · self-review layout','Reconcile the cash. Explain the obligation.','Work through the supplied hypothetical records with paper or a local worksheet. Store only structured answers here; no upload is required.')} ${sample()}<ol class="stepper" aria-label="Dossier sections"><li class="current">1 · Contract inputs</li><li>2 · Signed ledger</li><li>3 · Reconciliation</li><li>4 · Self-review</li></ol><div class="split"><section><h2>Hypothetical covered-call worksheet</h2><p>50 shares acquired at 100; one call written at strike 105 for premium 2 per unit; multiplier 50; total specified fee 5. No other costs, dividends, interest or taxes. Figures are from the P02 design fixture.</p><div class="table-wrap wide" tabindex="0" role="region" aria-label="Synthetic covered-call cash ledger"><table><caption>Signed opening cash flows · hypothetical currency units</caption><thead><tr><th scope="col">Event</th><th scope="col">Quantity</th><th scope="col">Unit amount</th><th scope="col" class="numeric">Signed cash</th></tr></thead><tbody><tr><th scope="row">Buy shares</th><td>50 shares</td><td>100 per share</td><td class="numeric">−5,000</td></tr><tr><th scope="row">Receive premium</th><td>1 × 50 units</td><td>2 per unit</td><td class="numeric">+100</td></tr><tr><th scope="row">Pay stated fee</th><td>Total</td><td>5</td><td class="numeric">−5</td></tr></tbody></table></div><figure style="margin:32px 0"><svg class="chart" viewBox="0 0 560 230" role="img" aria-labelledby="chart-title chart-desc"><title id="chart-title">Synthetic covered-call terminal profit and loss</title><desc id="chart-desc">At terminal underlying 80, net loss is 905. At 100, net profit is 95. At 105 or 110, net profit is 345. This is a terminal calculation, not a measure of interim funding risk. Exact values follow in the table.</desc><line class="axis" x1="72" y1="24" x2="72" y2="178"/><line class="axis" x1="72" y1="178" x2="510" y2="178"/><line class="axis" x1="72" y1="66.708" x2="510" y2="66.708"/><text x="8" y="29">+345</text><text x="42" y="72">0</text><text x="8" y="169">−905</text><path class="data-line" d="M90 163 L350 56.6 L415 30 L480 30"/><circle cx="90" cy="163" r="4"/><circle cx="350" cy="56.6" r="4"/><circle cx="415" cy="30" r="4"/><circle cx="480" cy="30" r="4"/><text x="80" y="202">80</text><text x="338" y="202">100</text><text x="402" y="202">105</text><text x="467" y="202">110</text><text x="160" y="224">Terminal underlying · currency units</text></svg><figcaption class="small muted">Illustrative terminal P/L, including the single stated fee. Both axes are currency units. Interim funding and assignment timing are separate questions.</figcaption></figure><details class="phase" data-chart-table><summary>Read the same chart as a table</summary><table><caption>Equivalent data for the synthetic P/L chart</caption><thead><tr><th scope="col">Terminal underlying</th><th scope="col">Net profit / loss</th></tr></thead><tbody>${[[80,-905],[100,95],[105,345],[110,345]].map(([x,y])=>`<tr><th scope="row">${x}</th><td>${y>0?'+':''}${y}</td></tr>`).join('')}</tbody></table></details><form id="dossier-form"><label for="reconciliation">Explain the reconciliation and one limitation</label><textarea id="reconciliation" maxlength="20000" aria-describedby="dossier-help"></textarea><p id="dossier-help" class="helper">Up to 20,000 characters across the entire dossier. This sample never awards professional certification.</p><label class="choice"><input id="critical-check" type="checkbox">I have checked the critical units, cash and assignment errors.</label><div class="actions">${button('Save draft','save-dossier')}<button class="primary" type="submit">Review my submission</button></div><p id="dossier-status" role="status"></p></form></section><aside class="side-rail"><h2>Evidence label</h2><p><strong>Self-reviewed project</strong><br>Numerical fields may be checked automatically. Qualitative reasoning remains your own assessment.</p><h2>Before final submission</h2><ul><li>All required fields complete</li><li>At least 85% on the authored rubric</li><li>No acknowledged critical error</li><li>Six foundation gates passed</li></ul><p>A reference solution appears only after a successful self-review. This design chart is an input specimen, not an assessment answer key.</p></aside></div>`);}
function admin(){return base(`${editorNav('admin')}${head('Editorial workspace · authorized role sample','Review the evidence before the page.','Draft editing, recorded review and publication are separate steps. This preview contains no learner writing.')}<div class="metadata">${badge('Editor + reviewer/publisher sample','')}<span>Password & security key required in product</span></div><div class="grid-3">${[['1','Draft to inspect','A specimen topic awaiting technical review.'],['5','Review dimensions','Technical, teaching, assessment, accessibility and rights.'],['0','Lessons published','Canonical snapshot remains unchanged.']].map(x=>`<div class="panel"><p class="large-number">${x[0]}</p><h3>${x[1]}</h3><p class="small muted">${x[2]}</p></div>`).join('')}</div><div class="section-heading"><h2>Draft review queue</h2>${link('maintenance','Maintenance & imports →')}</div><div class="list-row"><span class="number">M01.01</span><div><h3>${link('editor','Units and signs')}</h3><p>Illustrative revision 3 · scope changed · prior approvals require recheck</p></div>${badge('In review','warn')}${link('editor','Inspect draft','button')}</div>${note('Role boundaries remain visible','An administrator manages account access. They cannot edit or publish unless they also hold the corresponding editorial role.')}<div class="actions">${button('Review access-denied state','forbidden')}${button('Review recent-auth state','reauth-admin')}</div>`);}
function editor(){return base(`${editorNav('editor')}${crumbs([['admin','Editorial'],['','M01.01 draft']])}${head('M01.01 · draft specimen','Units and signs','Compare the current draft, preserve your base version and attach review evidence to the exact revision.')}<div class="editor-grid"><section><label for="draft-title">Title</label><input id="draft-title" value="Units and signs" maxlength="500"><label for="draft-text" style="margin-top:24px">Lesson source</label><textarea id="draft-text">## Read the units\n\nName the per-unit quote and the units per contract before calculating the signed cash flow.\n\nThis is a layout specimen, not reviewed teaching.</textarea><p class="helper">Restricted Markdown only. No raw HTML, scripts, embedded applications or executable notebooks.</p><div class="actions">${button('Save new draft','save-draft','primary')}${button('Compare versions','editor-conflict')}${button('Request review','request-review')}</div><p id="draft-status" role="status"></p></section><section class="panel"><p class="eyebrow">Authenticated preview · draft only</p><h2>Read the units</h2><p>Name the per-unit quote and the units per contract before calculating the signed cash flow.</p><div class="notice warn"><strong>Preview is not publication.</strong><p>This exact revision is visible only to an authorized editor/reviewer. It cannot be shared using a public preview token.</p></div><h3>Required review</h3>${['Technical and numerical','Teaching and preparation','Assessment and solution','Accessibility and readability','Sources and rights'].map((x,i)=>`<div class="review-check"><div><strong>${x}</strong><p>${i===0?'Illustrative review record awaiting decision.':'No approval for this revision yet.'}</p></div>${badge('Required','warn')}</div>`).join('')}</section></div>`);}
function publish(){return base(`${editorNav('publish')}${head('Publication review · specimen','Publish a coherent course, not an isolated change.','Every selected revision needs the right evidence. A changed draft clears its affected approvals.')}<ol class="stepper" aria-label="Publication workflow"><li>1 · Select revisions</li><li class="current">2 · Check reviews</li><li>3 · Confirm publication</li></ol><div class="split"><section><h2>Candidate manifest</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Candidate publication revisions"><table><caption>Illustrative selection · not a real complete release</caption><thead><tr><th scope="col">Content</th><th scope="col">Revision</th><th scope="col">Public use</th></tr></thead><tbody><tr><th scope="row">M01.01 · Units and signs</th><td>3 (sample)</td><td>Planned metadata</td></tr><tr><th scope="row">R01 · OCC reference</th><td>2 (sample)</td><td>Resource record</td></tr></tbody></table></div><div class="notice warn"><strong>Publication blocked: review is incomplete.</strong><p>Five review dimensions must cover the exact lesson revision. This sample is not a complete foundation course.</p></div><form id="review-form"><fieldset><legend>Record a review decision</legend><label for="review-type">Review dimension</label><select id="review-type"><option>Technical and numerical</option><option>Teaching and preparation</option><option>Assessment and solution</option><option>Accessibility</option><option>Sources and rights</option></select></fieldset><label for="review-findings">Evidence and findings</label><textarea id="review-findings" maxlength="16000"></textarea><label class="choice"><input type="checkbox" id="same-author">I am also the author of this sample revision.</label><div class="actions"><button type="submit">Record review</button>${button('Review publication confirmation','confirm-publish','primary')}</div><p id="review-status" role="status"></p></form></section><aside class="side-rail"><h2>At confirmation</h2><ul><li>Show the complete selected set.</li><li>Show changed public routes and assessments.</li><li>Require recent password and security-key authentication.</li><li>Recheck the current active release.</li></ul><p>A concurrent publication causes an explicit conflict. A withdrawal remains in force after rollback.</p>${link('maintenance','Review withdrawal and rollback →')}</aside></div>`);}
function maintenance(){return base(`${editorNav('maintenance')}${head('Editorial maintenance','Correct the record without losing the history.','Resource freshness, issue reports, exhausted assessment banks and import conflicts enter a private maintenance queue.')}<div class="grid-2"><section class="panel"><p class="label">Import preview · sample</p><h2>An edit needs reconciliation.</h2><p>M01.01 changed in the database after this package’s base revision. No draft head has been overwritten.</p>${badge('Conflict · not applied','warn')}<div class="actions">${button('Compare base / current / proposed','import-conflict')}</div><p class="helper">Missing records in a package do not mean deletion. Import never publishes.</p></section><section class="panel"><p class="label">Resource freshness · R01</p><h2>A link check is not a source review.</h2><p>Inspect the reviewed section and date independently from URL reachability. A due operational claim cannot remain “current” because a worker stopped.</p>${link('resource/R01','Inspect the source record →')}</section></div><h2 style="margin-top:40px">Controlled actions</h2><div class="actions">${button('Withdraw unsafe content','withdraw','danger')}${button('Review rollback','rollback')}${button('Review account role change','role-change')}</div><div class="list-row"><div><h3>Fresh assessment requested</h3><p>Sample queue item · no learner answers shown · target review within five business days</p></div>${badge('Pending','warn')}</div><div class="list-row"><div><h3>Volunteered content issue</h3><p>Only the report’s text and content reference are available to editors. Private notes and attempts are not.</p></div>${badge('To triage','warn')}</div>`);}
function methodology(){return base(`${head('Method & sources','Make the limits part of the lesson.','A link, a source review and a reproduced result are different kinds of evidence.')}<div class="grid-2"><section><h2>What a published lesson must contain</h2><ol><li>Objectives and preparation</li><li>Original explanation with defined units</li><li>A worked example and a misconception</li><li>Practice, changed-input transfer and useful feedback</li><li>Exact source scope, rights and accessible alternatives</li></ol><h2>What completion means</h2><p>Self-completion is your reading record. A fresh passed gate is bounded evidence for its reviewed outcomes. Project self-review is a different label. None promises professional competence or profitability.</p></section><section class="panel"><h2>Review scope, stated plainly</h2><p><strong>Access checked</strong><br>The URL was reached. That does not validate every claim.</p><p><strong>Selected sections reviewed</strong><br>The recorded sections were read. The rest is not implied.</p><p><strong>Current operational claim</strong><br>Requires instrument, jurisdiction, effective dates and a live review window. None of the current canonical rule records qualifies.</p>${link('resources','Inspect the reading library →')}</section></div>`);}
function reportPage(id){return base(`${head('Report content issue',`Help improve ${esc(id||'this page')}.`,'Verified learners can submit a private report linked to the page and version. It is not a public comment.')}<form id="issue-form" class="form-stack"><label for="issue-text">What should be checked?</label><textarea id="issue-text" maxlength="2000"></textarea><p class="helper">Up to 2,000 characters. Do not include private account, financial or brokerage information.</p><button class="primary" type="submit">Send report</button><p id="issue-status" role="status"></p></form>`);}
const reviewRoutes=[['home','Home / honest current counts','J01'],['learn','Foundation sequence','J01, J03'],['curriculum','Full phased roadmap','J01, J03'],['module/M01','Module / objectives / preparation','J01'],['topic/M01.01','Planned topic and subtopic scope','J01'],['lesson/M01.01','Reading / math / practice / notes','J02, J09–J11'],['resources','Library and filters','J04'],['resource/R01','Resource review scope / rights','J04'],['search?q=M21.01','Search / exact ID / empty ready filter','J05'],['paths','Seven planned paths','J03'],['path/PATH-BEGINNER','Shared path sequence','J03'],['projects','Project and capstone catalog','J13'],['project/PR01','Capability project specification','J13'],['capstone/C01','Capstone brief','J13'],['auth/register','Registration','J06'],['auth/verify','Verification / generic response','J06'],['auth/login','Login','J07'],['auth/forgot','Recovery request','J08'],['auth/reset','New password','J08'],['auth/mfa','Privileged security key','J07'],['auth/reauth','Session expired / recovery','J07'],['dashboard','Versioned dashboard / migration','J09'],['bookmarks','Saved places','J10'],['notes','Private note / conflict','J11'],['account','Preferences / export / deletion','J16'],['quiz','Untimed gate layout','J12'],['feedback','Failure / remediation / exhaustion','J12'],['dossier','Manual dossier / chart alternative','J13'],['admin','Editorial review queue','J14'],['editor','Draft / private preview / conflict','J14'],['publish','Review / manifest / confirmation','J14'],['maintenance','Import / withdrawal / rollback / roles','J15'],['report/R01','Volunteered issue','J15'],['methodology','Source and evidence policy','J01, J04']];
function reviewIndex(){return base(`${head('P06 review index','One design, across the whole journey.','Select a screen, then use the separate review toolbar to inspect loading, empty, error, offline, expired, conflict, withdrawn and exhausted-bank states.')}<div class="notice"><strong>Prototype boundary</strong><p>Canonical titles/scopes are real. Lesson, account, score and editorial states are synthetic. No network API, persistent browser storage, email, database or publication is involved.</p></div><div class="grid-3">${reviewRoutes.map(([r,label,j])=>link(r,`<p class="label">${j}</p><h3>${label}</h3><span class="small">Open screen →</span>`,'panel panel-link')).join('')}</div>`);}
function notFound(){return base(`${head('Page unavailable','That address doesn’t resolve.','The content may have moved, or the address may be incorrect.')}<div class="actions">${link('curriculum','Explore the curriculum','button primary')}${link('search','Search by topic or ID','button')}</div>`);}
function stateView(kind,html){if(kind==='ready')return html;
if(kind==='loading')return base(`${head('Loading','Finding your place…','Previously rendered public text stays readable while a request is retried.')}<section aria-busy="true" aria-label="Loading content"><p role="status">Loading content…</p><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div></section><p class="helper">Design state: shown by 500 ms. After ten seconds, offer a deliberate retry.</p>${button('Retry now','reset-state')}`);
if(kind==='empty')return base(`${head('Nothing here yet','A clear place to begin.','An empty list is not a service failure.')}<div class="notice"><strong>${route.page==='bookmarks'?'No saved bookmarks.':route.page==='search'||route.page==='resources'?'No matching results.':'No records for this sample view yet.'}</strong><p>${route.page==='resources'||route.page==='search'?'Remove a filter or try a broader phrase.':'Choose a lesson or inspect the curriculum to continue.'}</p></div><div class="actions">${button('Clear this review state','reset-state','primary')}${link('learn','Explore Foundations','button')}</div>`);
if(kind==='error')return base(`${head('Request interrupted','We couldn’t load this view.','Your previously confirmed work has not been changed.')}<div class="notice error" role="alert"><strong>Try again in a moment.</strong><p>If this keeps happening, quote reference DEMO-REQUEST in your support report. No internal error details are displayed.</p></div>${button('Try again','reset-state','primary')}`);
if(kind==='expired')return base(`${head('Session expired','Your writing needs a secure return.','Nothing new has been saved. Keep this tab open while you sign in again.')}<div class="notice warn"><strong>Unsaved writing remains only in this tab.</strong><p>Use a copy before closing the page. Signing out explicitly or switching accounts clears private text.</p></div><div class="actions">${link('auth/reauth','Sign in again','button primary')}${button('Show unsaved note for copying','copy-draft')}</div>`);
if(kind==='withdrawn')return base(`${head('Content withdrawn','This version needs correction.','The original material is unavailable while an important issue is reviewed.')}<div class="notice warn"><strong>Your historical record is preserved.</strong><p>A pinned requirement stays in your course denominator. Affected assessment evidence says Needs recheck; earlier scores are not silently recalculated.</p></div><div class="actions">${link('dashboard','View your learning record','button')}${link('curriculum','Explore available scope','button')}</div>`);
if(kind==='exhausted')return base(`${head('Assessment bank exhausted','Fresh evidence needs a fresh form.','Both reviewed forms have been seen. Rearranging the same questions does not make them new.')}<div class="notice warn"><strong>Continue learning while a replacement is reviewed.</strong><p>Repeated practice remains available but cannot satisfy a gate. A new assessment request has a five-business-day operational target, not an automatic approval.</p></div><div class="actions">${button('Request fresh assessment','fresh-request','primary')}${link('quiz','Inspect repeated-practice layout','button')}</div>`);
if(kind==='conflict')return base(`${head('Save conflict','Two versions need a deliberate choice.','Your unsaved text has not replaced the latest saved record.')}<div class="conflict-grid"><section class="panel"><h2>Saved version</h2><p>Record the unit before the calculation.</p></section><section class="panel"><h2>Your unsaved version</h2><p class="wrap">${esc(state.note||'Record both the unit and the sign before calculating cash.')}</p></section></div><div class="actions">${button('Keep editing my version','reset-state','primary')}${button('Compare in a dialog','conflict')}</div>`);
if(kind==='offline')return html.replace(/(<h1[^>]*>.*?<\/h1>)/s,`$1<div class="notice warn" role="alert"><strong>You’re offline. Changes are not saved.</strong><p>Already loaded reading is still available. Keep your draft in this tab; there is no background save queue.</p>${button('Reconnect and review','reset-state')}</div>`);
return html;}
function render(focus=true){const hash=location.hash;if(hash&&!hash.startsWith('#/'))return;const [path,query='']=(hash.slice(2)||'home').split('?');const [page,id='']=path.split('/');route={page,id,params:new URLSearchParams(query)};const views={home,learn,curriculum,module:()=>modulePage(id),topic:()=>topicPage(id),lesson,resources,resource:()=>resourceDetail(id),paths:pathsPage,path:()=>pathDetail(id),projects,project:()=>project(id),capstone:()=>project(id,true),search,auth:()=>auth(id),dashboard,bookmarks,notes,account,quiz,feedback,dossier,admin,editor,publish,maintenance,methodology,report:()=>reportPage(id),review:reviewIndex};$('#main').innerHTML=stateView(state.scenario,(views[page]||notFound)());document.title=($('#main h1')?.textContent||'Options field guide')+' — design preview';document.querySelectorAll('#primary-nav a').forEach(a=>{const name=a.hash.slice(2);const active=name===page||(name==='curriculum'&&['module','topic'].includes(page))||(name==='resources'&&page==='resource')||(name==='paths'&&page==='path')||(name==='projects'&&['project','capstone','dossier'].includes(page))||(name==='learn'&&page==='lesson');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#primary-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');if($('#main h1'))$('#main h1').tabIndex=-1;if($('[data-chart-table]')&&innerWidth<640)$('[data-chart-table]').open=true;if(focus){$('#main h1')?.focus();window.scrollTo(0,0);}announce('Opened '+($('#main h1')?.textContent||'view'));}
function modal(title,body,actions=''){restoreFocus=document.activeElement;$('#dialog-content').innerHTML=`<h2 id="dialog-title" tabindex="-1">${title}</h2>${body}<div class="actions">${actions}${button('Close','close-modal')}</div>`;$('#dialog').showModal();$('#dialog-title').focus();}
function closeModal(){if($('#dialog').open)$('#dialog').close();restoreFocus?.focus();}
function conflict(editor=false,imp=false){const body=`<p>${editor?'The content base changed. Saving a resolved draft creates another revision and clears affected approvals.':'Refresh the latest saved note, compare it with yours and deliberately reapply. There is no silent overwrite.'}</p><div class="conflict-grid"><section><h3>${imp?'Base and current':'Latest saved'}</h3><p>Record the unit before the calculation.</p></section><section><h3>${imp?'Proposed package':'Your unsaved text'}</h3><p>${esc(state.note||'Record the unit and sign before calculating cash.')}</p></section></div>`;modal(imp?'Import conflict':editor?'Draft conflict':'Your note changed in another tab',body,button('Keep my unsaved draft','close-modal','primary'));}
function resetScenario(){state.scenario='ready';$('#scenario').value='ready';}
$('#appearance').addEventListener('change',e=>{state.theme=e.target.value;applyTheme();});
function applyTheme(){document.documentElement.dataset.theme=state.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme;}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme==='system')applyTheme();});
$('#scenario').addEventListener('change',e=>{if($('#note-text'))state.note=$('#note-text').value;state.scenario=e.target.value;render();});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#primary-nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#dialog').addEventListener('close',()=>restoreFocus?.focus());
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a){resetScenario();if($('#note-text'))state.note=$('#note-text').value;if(a.hash===location.hash)render();}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
const actions={
'close-modal':closeModal,'reset-state':()=>{resetScenario();render();},
'bookmark':()=>{state.bookmark=!state.bookmark;b.textContent=state.bookmark?'Remove bookmark':route.page==='resource'?'Bookmark resource':'Bookmark topic';announce(state.bookmark?'Bookmarked in this preview only.':'Bookmark removed in this preview.');},
'remove-bookmark':()=>{state.bookmark=false;render();announce('Bookmark removed.');},
'complete':()=>{state.complete=!state.complete;b.textContent=state.complete?'Reopen topic':'Mark self-completed';$('#completion-status').textContent=state.complete?'Self-completed in this preview. This does not award assessment mastery.':'Topic reopened in this preview; assessment history is unchanged.';announce($('#completion-status').textContent);},
'solution':()=>{state.practiceSolution=true;$('#feedback').innerHTML=note('Solution viewed · practice only','A buyer pays out: −3 × 50 × 1 = −150 currency units. This practice cannot create fresh assessment evidence.');},
'conflict':()=>{if($('#note-text'))state.note=$('#note-text').value;conflict();},'editor-conflict':()=>conflict(true),'import-conflict':()=>conflict(true,true),
'copy-draft':()=>modal('Your unsaved writing',`<label for="copy-note">Select and copy before leaving</label><textarea id="copy-note" readonly>${esc(state.note||'No note text entered in this preview.')}</textarea>`),
'delete-note':()=>modal('Delete this private note?','<p>Its live text is removed immediately. Encrypted backup copies expire within 35 days. This preview only clears its in-memory sample.</p>',button('Delete note','confirm-delete-note','danger')),
'confirm-delete-note':()=>{state.note=state.noteSaved='';closeModal();render();announce('Note deleted in this preview.');},
'show-password':()=>{const i=$('#password');i.type=i.type==='password'?'text':'password';b.textContent=i.type==='password'?'Show password':'Hide password';},
'migration':()=>modal('Review a course version change','<p><strong>Current: 18 of 36 lessons.</strong> An illustrative next version adds one requirement. Your current course stays unchanged until you choose to move.</p><ul><li>Show added, changed and retired topic IDs.</li><li>Carry evidence only for identical or reviewed-equivalent revisions.</li><li>Preserve the old enrollment and scores.</li></ul>',button('Keep my current course','close-modal','primary')),
'email-change':()=>modal('Change your email','<label for="new-email">New email address</label><input type="email" id="new-email" autocomplete="email"><p class="helper">Recent authentication required. Keep the old login until the new address is verified; notify the old address.</p>',button('Preview verification request','email-request','primary')),
'email-request':()=>modal('Check the new address','<p>Sample confirmation only. The old login remains active. No email was sent.</p>'),
'export':()=>modal('Export requested','<p>Your request is pending. The product targets readiness within 24 hours and an owner-authenticated download available for 24 hours.</p><div class="notice"><strong>Sample ready state</strong><p>Your private export is ready until the displayed expiry time. No real export file exists in this prototype.</p></div>'),
'delete-account':()=>modal('Delete your account and learning records?','<p>Recent sign-in is required. Access ends immediately; live records are erased within seven days. This cannot be undone from an old browser tab.</p><label for="delete-confirm">Type DELETE to confirm the preview</label><input id="delete-confirm" autocomplete="off"><p id="delete-error" class="field-error" role="alert"></p>',button('Confirm deletion','confirm-delete-account','danger')),
'confirm-delete-account':()=>{if($('#delete-confirm').value!=='DELETE'){$('#delete-error').textContent='Type DELETE before continuing.';$('#delete-confirm').setAttribute('aria-invalid','true');$('#delete-confirm').setAttribute('aria-describedby','delete-error');$('#delete-confirm').focus();return;}state.note=state.noteSaved='';modal('Deletion accepted in the preview','<p>No real account existed. The product would revoke every session and provide a minimal receipt after accepting the request.</p>');},
'logout':()=>modal('Sign out of this device?',`<p>${state.note!==state.noteSaved?'You have unsaved writing. Copy it before signing out.':'This clears private in-memory state on the device.'}</p>`,button('Sign out','confirm-logout','primary')),
'logout-all':()=>modal('Sign out everywhere?','<p>This revokes every account session. Private local drafts are cleared on this device.</p>',button('Sign out everywhere','confirm-logout','primary')),
'confirm-logout':()=>{state.note=state.noteSaved='';state.signedIn=false;closeModal();navigate('auth/login');},
'save-answers':()=>{$('#quiz-status').textContent=state.scenario==='offline'?'Not saved. Keep this tab open.':'Answers saved in this preview only; no score is available before submission.';},
'abandon':()=>modal('Leave this attempt?','<p>Questions already shown remain exposed. Leaving does not restore a fresh assessment form.</p>',button('Leave attempt','abandon-confirm','danger')),
'abandon-confirm':()=>{closeModal();navigate('dashboard');},
'confirm-submit':()=>{state.quizFeedback=true;closeModal();navigate('feedback');},
'fresh-request':()=>modal('Fresh assessment requested','<p>Sample state: request pending. You can return to remediation or continue repeated practice. The operator target is five business days; this is not a promised automatic approval.</p>'),
'save-dossier':()=>{$('#dossier-status').textContent=state.scenario==='offline'?'Not saved. Your responses remain only in this tab.':'Draft saved in this preview only.';},
'forbidden':()=>modal('This action requires an editorial role','<p>An administrator or verified learner cannot open drafts without an editorial role and both authentication factors. No draft details would be returned.</p>'),
'reauth-admin':()=>{navigate('auth/mfa');},
'save-draft':()=>{$('#draft-status').textContent='New draft created in this preview. Previous review approvals no longer cover the changed revision.';},
'request-review':()=>{$('#draft-status').textContent='Review requested in this preview. Publication remains unavailable until every required review is recorded.';},
'confirm-publish':()=>modal('Publication is not ready','<p>The complete candidate and five required reviews must pass server checks. This sample selection cannot be activated.</p><p>A valid final confirmation would list the selected revisions, public impact and expected active release before its deliberate Publish action.</p>'),
'withdraw':()=>modal('Withdraw this content?','<p>Provide a safe public explanation, impacted stable IDs and reason. This immediately blocks delivery and may mark assessment evidence Needs recheck.</p><label for="withdraw-reason">Public explanation</label><textarea id="withdraw-reason" maxlength="4000"></textarea>',button('Preview withdrawal receipt','withdraw-receipt','danger')),
'withdraw-receipt':()=>modal('Withdrawal receipt · sample','<p>The product would confirm the new publication generation and affected identities. Its safety restriction would survive rollback. No live content changed here.</p>'),
'rollback':()=>modal('Review a rollback','<p>A rollback creates a new publication event selecting an earlier coherent manifest. It preserves withdrawals, newer rights exclusions and all learner transactions.</p><p>Show the target version, changed routes and revalidated exclusions before confirmation.</p>'),
'role-change':()=>modal('Review an access change','<p>Only a recently authenticated administrator can change privileged roles. Two recoverable authenticators are required before activation; role changes revoke existing sessions.</p><p>The UI lists roles and account state, not private notes or answers. Suspending an account revokes access; restoring it cannot revive a deleting account.</p>')};actions[action]?.();});
document.addEventListener('input',e=>{if(e.target.id==='note-text'){state.note=e.target.value;$('#note-status').textContent='Unsaved changes in this tab.';}if(e.target.name==='answer'&&route.page==='quiz')state.quizAnswer=e.target.value;});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;
if(f.id==='resource-filters'){const p=new URLSearchParams();new FormData(f).forEach((v,k)=>{if(v)p.set(k,v)});navigate('resources?'+p);}
if(f.id==='search-form'){const p=new URLSearchParams();p.set('q',$('#global-q').value);if(f.elements.ready.checked)p.set('visibility','LESSON');navigate('search?'+p);}
if(f.id==='practice-form'){const v=$('#practice-answer').value.trim();if(!/^-?\d+(\.\d+)?$/.test(v)){$('#practice-answer').setAttribute('aria-invalid','true');$('#feedback').innerHTML='<p class="field-error" id="practice-error">Enter a signed number, such as −150 using the keyboard minus sign.</p>';$('#practice-answer').setAttribute('aria-describedby','practice-help practice-error');$('#practice-answer').focus();return;}$('#practice-answer').removeAttribute('aria-invalid');$('#practice-answer').setAttribute('aria-describedby','practice-help');$('#feedback').innerHTML=note(Number(v)===-150?'The units and sign agree.':'Check the direction of cash.',Number(v)===-150?'−3 × 50 × 1 = −150 currency units. This is practice feedback, not gate evidence.':'A buyer pays out, so the signed entry is negative. Multiply the per-unit quote by the contract multiplier, then keep the sign. Try again.');}
if(f.id==='note-form'){state.note=$('#note-text').value;if(state.scenario==='offline'){$('#note-status').textContent='Not saved. Copy your draft before leaving this tab.';return;}if(!state.note.trim()){$('#note-status').textContent='Write a note before saving, or delete the existing note.';$('#note-text').focus();return;}state.noteSaved=state.note;$('#note-status').textContent='Saved in this preview only. No server or browser storage was used.';}
if(f.id==='auth-form'){const mode=f.dataset.mode;const email=f.elements.email;if(email&&(!email.value||!email.validity.valid)){$('#email-error').hidden=false;$('#email-error').textContent='Enter a valid email address.';email.setAttribute('aria-invalid','true');email.setAttribute('aria-describedby','email-error');email.focus();return;}if(email){email.removeAttribute('aria-invalid');$('#email-error').hidden=true;}const pass=f.elements.password;if(pass&&(!pass.value||(['register','reset'].includes(mode)&&[...pass.value].length<15))){$('#auth-result').textContent='Use a password of at least 15 characters for registration/reset, or enter your current password to sign in.';pass.setAttribute('aria-invalid','true');pass.setAttribute('aria-describedby','password-help auth-result');pass.focus();return;}if(mode==='register'&&!f.elements.eligible.checked){$('#auth-result').textContent='Confirm the eligibility policy before registering.';f.elements.eligible.focus();return;}if(['register','forgot','verify'].includes(mode))$('#auth-result').textContent='If eligible, check your email for the next step. Design sample only; no message was sent.';else if(mode==='reset')$('#auth-result').innerHTML=`Password reset confirmation layout. Other sessions would be revoked. ${link('auth/login','Return to sign in')}`;else if(mode==='mfa')navigate('admin');else{state.signedIn=true;navigate(mode==='reauth'?'notes':'dashboard');}}
if(f.id==='preferences-form')$('#preferences-status').textContent='Preferences updated in this preview only.';
if(f.id==='quiz-form'){state.quizAnswer=f.elements.answer.value;modal('Submit this assessment?',`<p>${state.quizAnswer?'One sample answer is selected.':'This sample question is unanswered. In the product, unanswered items score zero only after explicit confirmation.'}</p><p>Submission finalizes the answers. Feedback becomes available only for the assigned submitted form.</p>`,button(state.quizAnswer?'Submit sample':'Confirm unanswered and submit','confirm-submit','primary'));}
if(f.id==='remediation-form')$('#remediation-status').textContent=$('#explanation').value.trim()?'Explanation recorded in this preview. The product also verifies the required transfer practice before another fresh form is eligible.':'Explain what you learned before recording remediation.';
if(f.id==='dossier-form'){if(!$('#critical-check').checked||!$('#reconciliation').value.trim()){$('#dossier-status').textContent='Complete the explanation and critical-error acknowledgment before review.';$('#reconciliation').focus();return;}modal('Review the complete dossier','<p>Confirm all structured fields, authored rubric scores and critical checks. This prototype has no full rubric or score engine and cannot approve the dossier.</p><p>The product labels a successful result Self-reviewed project, preserves the submitted version and then releases its reference solution.</p>');}
if(f.id==='review-form')$('#review-status').textContent=$('#review-findings').value.trim()?'Review recorded for the sample revision with honest author/reviewer attribution. Other review dimensions remain required.':'Enter evidence and findings before recording a decision.';
if(f.id==='issue-form')$('#issue-status').textContent=$('#issue-text').value.trim()?'Report received in this preview only. No external message was sent.':'Describe what needs checking before submitting.';
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog').open&&$('#primary-nav').classList.contains('open')){$('#primary-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').focus();}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&!a.hash.startsWith('#/')){const target=document.getElementById(a.hash.slice(1));if(target){target.tabIndex=-1;target.focus();}}});
window.addEventListener('hashchange',()=>render());
window.addEventListener('beforeunload',e=>{if(state.note!==state.noteSaved){e.preventDefault();e.returnValue='';}});
render(false);
